import sys
# Ensure project root is on sys.path before importing any project modules
sys.path.insert(0, r'/home/carme/ATPA_CIF')

# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from data_loader import build_train_val_dataloaders
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Define hyperparameters
NUM_EPOCHS = 20
BATCH_SIZE = 32
LEARNING_RATE = 0.001
DROPOUT_RATE = 0.5
L2_REGULARIZATION = 1e-4
NUM_SPECIES = 206

# Data paths
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")

# Load data
train_loader, val_loader = build_train_val_dataloaders(
    metadata_csv=METADATA_FILE,
    audio_dir=DATA_DIR,
    batch_size=BATCH_SIZE,
    augment=True,
    val_split=0.2,
)

# Define the model
class BirdCLEFModel(nn.Module):
    def __init__(self, num_species):
        super(BirdCLEFModel, self).__init__()
        self.conv_layers = nn.Sequential(
            nn.Conv2d(1, 32, 3, padding=1), nn.BatchNorm2d(32), nn.ReLU(),
            nn.Conv2d(32, 64, 3, padding=1), nn.BatchNorm2d(64), nn.ReLU(),
        )
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Linear(64, 128), nn.ReLU(), nn.Dropout(DROPOUT_RATE),
            nn.Linear(128, num_species)
        )

    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Instantiate the model
model = BirdCLEFModel(NUM_SPECIES).to('cuda')

# Loss and optimizer
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=LEARNING_RATE, weight_decay=L2_REGULARIZATION)

# Early stopping parameters
early_stopping_patience = 5
best_auc = 0.0
epochs_without_improvement = 0

# Training loop
for epoch in range(NUM_EPOCHS):
    model.train()
    total_loss = 0.0
    
    for batch_count, (inputs, labels) in enumerate(train_loader):
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        
        try:
            optimizer.zero_grad()
            outputs = model(inputs)
            loss = criterion(outputs, labels.float())
            loss.backward()
            optimizer.step()
            
            total_loss += loss.item()
            torch.cuda.empty_cache()  # Prevent GPU fragmentation
        except RuntimeError as e:
            if 'out of memory' in str(e):
                print(f"CUDA out of memory. Clearing cache and reducing batch size from {BATCH_SIZE} to {BATCH_SIZE // 2}.")
                torch.cuda.empty_cache()
                BATCH_SIZE //= 2
                continue
        
        # Optionally, break for fast iteration
        if batch_count >= 10:
            break

    # Evaluate on validation set
    model.eval()
    all_preds = []
    all_labels = []

    with torch.no_grad():
        for inputs_val, labels_val in val_loader:
            inputs_val, labels_val = inputs_val.to('cuda'), labels_val.to('cuda')
            outputs_val = model(inputs_val)
            all_preds.extend(outputs_val.cpu().numpy())
            all_labels.extend(labels_val.cpu().numpy())

    auc = roc_auc_score(all_labels, all_preds, average='weighted')
    print(f"Epoch {epoch+1}/{NUM_EPOCHS}, Training Loss: {total_loss / (batch_count + 1):.4f}, Validation AUC: {auc:.4f}")

    # Early stopping check
    if auc > best_auc:
        best_auc = auc
        epochs_without_improvement = 0
    else:
        epochs_without_improvement += 1

    if epochs_without_improvement >= early_stopping_patience:
        print(f"Early stopping after {epochs_without_improvement} epochs without improvement.")
        break

# Save metrics and model
metrics = {
    "final_train_loss": total_loss / (batch_count + 1),
    "final_auc": auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": epoch + 1,
    "batch_size": BATCH_SIZE,
    "training_samples": len(train_loader.dataset),
    "eval_samples": len(val_loader.dataset)
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: " + json.dumps(metrics))
torch.save(model.state_dict(), 'model.pt')